function blocks(page){const rows=[];function walk(x){if(!x||typeof x!=='object')return;if('block_type'in x||'block_style_type'in x)rows.push(x);for(const v of Object.values(x))if(typeof v==='object')Array.isArray(v)?v.forEach(walk):walk(v);}walk(page.modules);return rows;}
const validId=id=>{if(!/^[a-zA-Z0-9]{8,20}$/.test(String(id||'')))throw Error('火龙剧集 ID 无效');return String(id);};
const idFromLink=link=>{const m=/^huolong:\/\/drama\/([a-zA-Z0-9]{8,20})$/.exec(String(link||''));if(!m)throw Error('火龙链接无效');return m[1];};
