const endpoint='https://hongguo.openharbor.dpdns.org/v1/huolong/page';
async function responseData(r){const status=Number(r?.statusCode??r?.status??200);if(status<200||status>=300)throw Error('火龙接口 HTTP '+status);let d=r.data;if(typeof d==='string')d=JSON.parse(d);if(d?.error)throw Error(d.error.message||'火龙接口失败');return d;}
